const cfg = $json;
if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey in Config node');

const baseUrl = (cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const locationId = cfg.locationId;

const expected = {
  'Warm Leads': [
    'Warm - New',
    'Warm - Qualified (MQL)',
    'Warm - Routed to Outreach',
    'Warm - Nurture Active',
    'Warm - Disqualified',
  ],
  'Sales Outreach': [
    'Outreach - New',
    'Outreach - Attempting Contact',
    'Outreach - Engaged',
    'Outreach - Meeting Requested',
    'Outreach - Booked',
    'Outreach - Unresponsive',
  ],
  'Sales': [
    'Sales - Discovery Scheduled',
    'Sales - Discovery Completed',
    'Sales - Proposal Sent',
    'Sales - Negotiation',
    'Sales - Closed Won',
    'Sales - Closed Lost',
  ],
};

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

let data;
try {
  data = await doHttpRequest.call(this, {
    method: 'GET',
    url: `${baseUrl}/opportunities/pipelines?locationId=${encodeURIComponent(locationId)}`,
    headers,
    json: true,
  });
} catch (err) {
  const code = err?.statusCode || err?.httpCode || 500;
  const body = err?.response?.body || err?.message || err;
  throw new Error(`Failed to fetch pipelines: ${code} ${JSON.stringify(body)}`);
}

const pipelines = Array.isArray(data?.pipelines)
  ? data.pipelines
  : Array.isArray(data?.data?.pipelines)
    ? data.data.pipelines
    : Array.isArray(data)
      ? data
      : [];

const byName = new Map();
for (const p of pipelines) {
  if (p?.name) byName.set(p.name, p);
}

const missingPipelines = [];
const missingStages = [];
const idMap = {};

for (const [pipelineName, stages] of Object.entries(expected)) {
  const pipeline = byName.get(pipelineName);
  if (!pipeline) {
    missingPipelines.push(pipelineName);
    continue;
  }

  idMap[pipelineName] = {
    pipelineId: pipeline.id || pipeline._id || null,
    stages: {},
  };

  const stageByName = new Map((pipeline.stages || []).map((s) => [s.name, s]));
  for (const stageName of stages) {
    const st = stageByName.get(stageName);
    if (!st) {
      missingStages.push({ pipelineName, stageName });
    } else {
      idMap[pipelineName].stages[stageName] = st.id || st._id || null;
    }
  }
}

if (missingPipelines.length || missingStages.length) {
  const report = {
    status: 'BLOCKED_MANUAL_CREATE_REQUIRED',
    locationId,
    missingPipelines,
    missingStages,
    note: 'Create missing pipelines/stages in GHL UI exactly as named, then re-run this workflow.',
  };
  throw new Error(JSON.stringify(report, null, 2));
}

return [{
  json: {
    status: 'READY',
    locationId,
    pipelineStageIdMap: idMap,
  },
}];
